package dk.jamesbabz.madkursus.outbound.mealplan.details;
import java.util.*; import dk.jamesbabz.madkursus.service.models.PlannedRecipeStatus; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface MealPlanJpaRepository extends JpaRepository<MealPlanEntity,UUID>{Optional<MealPlanEntity> findByIdAndUserId(UUID id,UUID userId);List<MealPlanEntity> findAllByUserIdOrderByUpdatedAtDesc(UUID userId);@Query("select (count(p)>0) from PlannedRecipeEntity p where p.mealPlan.userId=:userId and p.recipe.id=:recipeId and p.status=dk.jamesbabz.madkursus.service.models.PlannedRecipeStatus.PLANNED")boolean existsPlanned(@Param("recipeId")UUID recipeId,@Param("userId")UUID userId);@Modifying @Query("update PlannedRecipeEntity p set p.recipe=null where p.mealPlan.userId=:userId and p.recipe.id=:recipeId and p.status in :statuses")int detachHistorical(@Param("recipeId")UUID recipeId,@Param("userId")UUID userId,@Param("statuses")Collection<PlannedRecipeStatus> statuses);long deleteByIdAndUserId(UUID id,UUID userId);}
